{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례상 옷에 흡착된 담배 성분이 다시 배출되는 3차 흡연이 간접흡연에 포함되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례 제2조제3호에 따르면, 간접흡연은 비흡연자가 흡연 시 발생하는 유해 물질에 노출되는 것을 뜻하며, 담배 연기에 직접 노출되는 2차 흡연과 흡연자의 옷, 벽, 가구 등에 흡착된 유해 물질이 다시 공기 중으로 배출되는 과정을 거쳐 비흡연자에게 보다 장기간 피해를 미칠 수 있는 3차 흡연을 모두 포함한다. 따라서 옷에 남았다가 나오는 담배 성분은 간접흡연에 포함된다.",
          "b_ids": "금연:제2조제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
